const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const headers = { apikey: SK, Authorization: `Bearer ${SK}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
const prev = await (await fetch(`${SUPA}/rest/v1/sprints?status=eq.closed&order=sprint_number.desc&limit=1&select=sprint_number,end_date`, { headers })).json();
const prevNum = prev[0]?.sprint_number || 0;
const newNum = prevNum + 1;
const startDate = prev[0]?.end_date || new Date().toISOString().slice(0,10);
const endDate = new Date(startDate + 'T12:00:00Z'); endDate.setUTCDate(endDate.getUTCDate() + 1);
const endDateStr = endDate.toISOString().slice(0,10);
const projects = ['Vespera', 'Mission Control', 'Infrastructure'];
for (const project of projects) {
  await fetch(`${SUPA}/rest/v1/sprints`, { method: 'POST', headers, body: JSON.stringify({ name: `sprint-${newNum}`, project, sprint_number: newNum, start_date: startDate, end_date: endDateStr, status: 'active', goal: `Sprint ${newNum} — continue active work` }) });
}
const issues = await (await fetch(`${SUPA}/rest/v1/issues?sprint=eq.${startDate}&status=in.(open,in_progress,code_review,product_review,approved)&select=id`, { headers })).json();
const kickoff = `🚀 Sprint ${newNum} Started\n📅 ${startDate} → ${endDateStr} (24h)\n📋 Issues in sprint: ${issues.length}\n🏗️ Projects: ${projects.join(', ')}\n⏰ Sprint closes at 7am EDT tomorrow`;
return [{ json: { ok: true, sprintNumber: newNum, startDate, endDate: endDateStr, issueCount: issues.length, kickoff } }];
